import numpy as np


def r(x):
    # Maps the domain [0, 1] to itself by reflecting around 0.5.
    # This reflects the target mean mu = 4x - 2 to -mu.
    return 1.0 - float(x)


def R(y_orig, y_new):
    # Since the target distributions for x and 1-x are symmetric about 0,
    # the post-warmup chain means should sum to approximately 0.
    return bool(np.isclose(y_orig + y_new, 0.0, atol=0.8))
